  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(notesKey(sheet), asOf),
    queryFn: () => getJson<Note[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/notes`, asOf)),
    enabled: sheet !== '',
  });
}
